int16_t currentCursorY = 0;
int16_t currentCursorX = 5;
bool screenCleared = false;

SemaphoreHandle_t bufferMutex = NULL;

int bufferHead = 0;
int bufferCount = 0;
int scrollOffset = 0;
std::string lineBuffer[SCROLL_BUFFER_SIZE];

void drawWallpaper() {
    tft.fillRect(0, 0, 80, 80, 0xE987);
    // rect 1 copy 1
    tft.fillRect(0, 80, 80, 80, 0x61B0);
    // rect 1 copy 2
    tft.fillRect(0, 160, 80, 80, 0x2E0F);
    // rect 1 copy 3
    tft.fillRect(80, 0, 80, 80, 0xE521);
    // rect 1 copy 4
    tft.fillRect(80, 80, 80, 80, 0x1AF6);
    // rect 1 copy 5
    tft.fillRect(80, 160, 80, 80, 0x63F1);
    // rect 1 copy 6
    tft.fillRect(160, 0, 80, 80, 0xFAA4);
    // rect 1 copy 7
    tft.fillRect(160, 80, 80, 80, 0xCEE7);
    // rect 1 copy 8
    tft.fillRect(160, 160, 80, 80, 0x651D);
    // rect 1 copy 9
    tft.fillRect(240, 0, 80, 80, 0x6225);
    // rect 1 copy 10
    tft.fillRect(240, 80, 80, 80, 0x1B9B);
    // rect 1 copy 11
    tft.fillRect(240, 160, 80, 80, 0xC0E5);
}

void renderScreen(){
    if (bufferMutex != NULL) {
        xSemaphoreTake(bufferMutex, portMAX_DELAY);
    }
    
    Theme current = getCurrentTheme();
    // tft.fillScreen(current.bg);
    drawWallpaper();
    tft.setTextColor(current.fg, current.bg);

    int total = bufferCount;
    int start = total - LINES_ON_SCREEN - scrollOffset;
    if (start < 0) start = 0;

    int y = 0;
    for(int i = start; i < total && i < start + LINES_ON_SCREEN + 1; i++){
        int idx = (bufferHead - total + i + SCROLL_BUFFER_SIZE) % SCROLL_BUFFER_SIZE;
        tft.setCursor(5, y * LINE_HEIGHT);
        tft.println(lineBuffer[idx].c_str());
        y++;
    }

    currentCursorY = y * LINE_HEIGHT;

    if (scrollOffset > 0){
        tft.setTextColor(current.bg , current.bg ^ 0xFFFF);
        tft.setCursor(260, 0);
        char ind[16];
        snprintf(ind, sizeof(ind), "^%d", scrollOffset);
        tft.print(ind);
        vTaskDelay(2 / portTICK_PERIOD_MS);
        tft.endWrite();
        tft.setTextColor(current.fg, current.bg);
        
    }
    
    if (bufferMutex != NULL) {
        xSemaphoreGive(bufferMutex);
    }
}

void scrollUp(int lines){
    if (bufferMutex != NULL) {
        xSemaphoreTake(bufferMutex, portMAX_DELAY);
    }
    
    int oldOffset = scrollOffset;
    int maxScroll = bufferCount - LINES_ON_SCREEN;

    if (maxScroll < 0) maxScroll = 0;

    scrollOffset += lines;

    if (scrollOffset > maxScroll) scrollOffset = maxScroll;
    
    if (bufferMutex != NULL) {
        xSemaphoreGive(bufferMutex);
    }
    
    if (scrollOffset != oldOffset) {
        renderScreen();
    }
}

void scrollDown(int lines){
    if (bufferMutex != NULL) {
        xSemaphoreTake(bufferMutex, portMAX_DELAY);
    }
    
    int oldOffset = scrollOffset;
    scrollOffset -= lines;
    if (scrollOffset < 0) scrollOffset = 0;
    
    if (bufferMutex != NULL) {
        xSemaphoreGive(bufferMutex);
    }
    
    if (scrollOffset != oldOffset) {
        renderScreen();
    }
}

void scrollToBottom(){
    if (bufferMutex != NULL) {
        xSemaphoreTake(bufferMutex, portMAX_DELAY);
    }
    if (0 == scrollOffset) {
        if (bufferMutex != NULL) {
            xSemaphoreGive(bufferMutex);
        }
        return;
    }
    scrollOffset = 0;
    
    if (bufferMutex != NULL) {
        xSemaphoreGive(bufferMutex);
    }
    
    renderScreen();
}

void scrollToTop(){
    if (bufferMutex != NULL) {
        xSemaphoreTake(bufferMutex, portMAX_DELAY);
    }
    
    int maxScroll = bufferCount - LINES_ON_SCREEN;

    if (maxScroll < 0){
      maxScroll = 0;  
    }

    if (maxScroll == scrollOffset) {
        if (bufferMutex != NULL) {
            xSemaphoreGive(bufferMutex);
        }
        return;
    }

    scrollOffset = maxScroll;
    
    if (bufferMutex != NULL) {
        xSemaphoreGive(bufferMutex);
    }
    
    renderScreen();
}

uint8_t sin8(int angle) {
    return (uint8_t)((sin(angle * M_PI / 128.0) + 1.0) * 127.5);
}

void initDisplay() {
    delay(150);
#if defined(DEVICE_RP2350)
    SPI.setTX(TFT_MOSI);
    //SPI.setRX(28);  // Dummy RX pin (GPIO28 - not used)
    SPI.setSCK(TFT_SCLK);
    // SPI.setCS(TFT_CS);
    SPI.begin();
#else
    SPI.begin(TFT_SCLK, -1, TFT_MOSI, TFT_CS);
    SPI.setFrequency(40000000);
#endif
    tft.init(240, 320);
    tft.setRotation(1);
    tft.setTextWrap(true);
    tft.invertDisplay(false);
    for(int i = 0; i < SCROLL_BUFFER_SIZE; ++i){
        lineBuffer[i] = "\n";
    }
    
    if (bufferMutex == NULL) {
        bufferMutex = xSemaphoreCreateMutex();
    }
    applyTheme();
    currentCursorY = 0;
}


void applyTheme() {
    Theme current = getCurrentTheme();
    // tft.fillScreen(current.bg);
    drawWallpaper();
    tft.setTextColor(current.fg);
    tft.setCursor(5, 0);
    currentCursorY = 0;
}

void clearScreen() {
    if (bufferMutex != NULL) {
        xSemaphoreTake(bufferMutex, portMAX_DELAY);
    }
    
    Theme current = getCurrentTheme();
    // tft.fillScreen(current.bg);
    drawWallpaper();
    tft.setCursor(5, 0);
    currentCursorY = 0;
    scrollOffset = 0;
    tft.setTextColor(current.fg, current.bg);
    screenCleared = true;
    // print(">" + getDeviceName() + "@Mini:");
    
    if (bufferMutex != NULL) {
        xSemaphoreGive(bufferMutex);
    }
}

void newPage() {
    Theme current = getCurrentTheme();
    // tft.fillScreen(current.bg);
    drawWallpaper();
    tft.setCursor(5, 0);
    currentCursorY = 0;
    tft.setTextColor(current.fg, current.bg);
}

void printLine(const std::string& s) {
    Serial.println(s.c_str());

    if (bufferMutex != NULL) {
        xSemaphoreTake(bufferMutex, portMAX_DELAY);
    }
    
    lineBuffer[bufferHead] = s;
    bufferHead = (bufferHead + 1) % SCROLL_BUFFER_SIZE;
    if (bufferCount < SCROLL_BUFFER_SIZE) bufferCount++;
    
    bool wasScrolled = (scrollOffset > 0);

    if (bufferMutex != NULL) {
        xSemaphoreGive(bufferMutex);
    }
    
    if (wasScrolled) {
        scrollToBottom();
        return;
    }
    
    if (scrollOffset == 0) {
        Theme current = getCurrentTheme();

        if (currentCursorY + LINE_HEIGHT > MAX_Y) {
            newPage();
            // renderScreen();

            vTaskDelay(1 / portTICK_PERIOD_MS);
            return;
        }

        tft.setCursor(5, currentCursorY);
        tft.setTextColor(current.fg, current.bg);
        tft.println(s.c_str());
        currentCursorY = tft.getCursorY();
        currentCursorX = tft.getCursorX();

        vTaskDelay(1 / portTICK_PERIOD_MS);
    }
}
