void drawScreen() {
    tft.fillScreen(0x0);

    // rect 17
    tft.fillRect(0, 1, 320, 239, 0xFFFF);

    // menu_information_sign
    tft.drawBitmap(4, 215, image_menu_information_sign_bits, 15, 16, 0x20E6);

    // misios
    tft.drawRGBBitmap(88, 60, image_misios_pixels, 144, 120);

    // Certification1
    tft.drawBitmap(4, 150, image_Certification2_bits, 103, 56, 0x0);

    // puffy
    tft.drawRGBBitmap(250, 0, image_puffy_pixels, 70, 60);

    // string 6
    tft.setTextColor(0x0);
    tft.setTextWrap(false);
    tft.setFont(&FreeSans9pt7b);
    tft.setCursor(21, 227);
    tft.println("github.com/VuqarAhadli/MiniOS-ESP");
    screenLocked = true;
    while (true) {
        if (Serial.available()) {
            char c = Serial.read();
            if (c == '\n') {
                tft.setFont(NULL);
                clearScreen();
                screenLocked = false;
                break;
            }
        }
        vTaskDelay(10 / portTICK_PERIOD_MS);
    }

}
